pub fn same_divide_sphere64_table(tbl_index64: u8) -> Option<&'static [[f32; 3]]> {
    let n = tbl_index64 as usize + 2;
    if n < 2 || n > 64 {
        return None;
    }
    SAME_DIVIDE_SPHERE64_TABLES.get(n - 2).copied()
}

